```python
def transform(data):
    orders = data["orders"]
    filtered = [r for r in orders if r.get("price") is not None and r["price"] > 100]
    agg = {}
    for r in filtered:
        cid = r.get("customer_id")
        if cid not in agg:
            agg[cid] = {"customer_id": cid, "total_spent": 0, "order_count": 0}
        p = r.get("price")
        agg[cid]["total_spent"] += p if p is not None else 0
        agg[cid]["order_count"] += 1
    return list(agg.values())
```

